-- Espaciales (plan de fusión, Luciano et al., 2009): transformación de funciones como última fase.
-- Vincular Mutuamente: «pintar desde un lado» con umbral («la pintura llega justo hasta X»):
-- A → B (desde el lado de A) y B → A (desde el lado de B); la respuesta se deduce con seguridad.
-- Redes: «Empiezas a pintar por arriba y vas bajando. ¿Qué pintarás lo último?» (exige ordenar
-- los tres: C → A y A → C). Se retira «Transferir Funciones a través de Relaciones Espaciales»;
-- su búsqueda con cajas reales pasa a «Fuera de la tableta».
begin;
update clases_rft_base c set consignas = $j${"test_mutuo:A→B": "El gato está encima de la mesa. ¿Qué está debajo del gato?", "entrenamiento:B→A": "El gato está encima de la mesa. ¿Qué está encima de la mesa?", "transformacion_funciones:A→B": "El gato está encima de la mesa. Empiezas a pintar por arriba y la pintura llega justo hasta el gato. ¿Qué queda sin pintar?", "transformacion_funciones:B→A": "El gato está encima de la mesa. Empiezas a pintar por abajo y la pintura llega justo hasta la mesa. ¿Qué queda sin pintar?"}$j$::jsonb from programas_base pb where pb.id = c.programa_base_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Espaciales' and c.nombre = 'Clase 1';
update clases_rft c set consignas = c.consignas || jsonb_build_object('transformacion_funciones:A→B', $j$El gato está encima de la mesa. Empiezas a pintar por arriba y la pintura llega justo hasta el gato. ¿Qué queda sin pintar?$j$, 'transformacion_funciones:B→A', $j$El gato está encima de la mesa. Empiezas a pintar por abajo y la pintura llega justo hasta la mesa. ¿Qué queda sin pintar?$j$) from programas_alumno pa join programas_base pb on pb.id = pa.programa_base_id where pa.id = c.programa_alumno_id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Espaciales' and c.nombre = 'Clase 1';
