update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "B", "destino": "A"}, {"fase": "test_mutuo", "origen": "A", "destino": "B"}, {"fase": "transformacion_funciones", "origen": "A", "destino": "B"}, {"fase": "transformacion_funciones", "origen": "B", "destino": "A"}]'::jsonb,
  objetivo = objetivo || $t$ Además, transforma una función a través de la relación («Empiezas a pintar por arriba y la pintura llega justo hasta el gato. ¿Qué queda sin pintar?» → la mesa).$t$,
  instrucciones_terapeuta = regexp_replace(regexp_replace(instrucciones_terapeuta, E'\n(Generalización \\(sondas\\):)', $t$
Fase 3 - Test de Transformación de Funciones a través de la relación mutua, sin entrenamiento directo (Luciano et al., 2009):

1. Enuncie la relación y una situación con un umbral («justo») desde el lado de uno de los dos, y pregunte por el otro: "El gato está encima de la mesa. Empiezas a pintar por arriba y la pintura llega justo hasta el gato. ¿Qué queda sin pintar?" (respuesta: la mesa). Desde el otro lado se pregunta por el primero: "… Empiezas a pintar por abajo y la pintura llega justo hasta la mesa. ¿Qué queda sin pintar?" (respuesta: el gato).
2. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta.
3. Elegir el que nombra la frase de la pintura indica que no transforma la función a través de la relación.

\1$t$), E'(- Test de vínculo mutuo:[^\n]*\n)', $t$\1- Transformación de funciones: A → B (pintando desde el lado de A: "¿Qué queda sin pintar?"; la respuesta es B) y B → A (desde el lado de B; la respuesta es A)
$t$)
where clinica_id is null and nombre = 'Vincular Mutuamente Relaciones Espaciales' and instrucciones_terapeuta not like '%Fase 3 - Test de Transformación de Funciones a través de la relación mutua%';
update programas_alumno pa set objetivo = pb.objetivo, secuencia_rft = pb.secuencia_rft, instrucciones_terapeuta = pb.instrucciones_terapeuta
from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Vincular Mutuamente Relaciones Espaciales';

update programas_base set secuencia_rft = '[{"fase": "entrenamiento", "origen": "B", "destino": "A"}, {"fase": "entrenamiento", "origen": "C", "destino": "B"}, {"fase": "test_mutuo", "origen": "A", "destino": "B"}, {"fase": "test_mutuo", "origen": "B", "destino": "C"}, {"fase": "test_combinatorio", "origen": "C", "destino": "A"}, {"fase": "test_combinatorio", "origen": "A", "destino": "C"}, {"fase": "transformacion_funciones", "origen": "C", "destino": "A"}, {"fase": "transformacion_funciones", "origen": "A", "destino": "C"}]'::jsonb,
  objetivo = objetivo || $t$ Además, transforma una función a través de la red («Empiezas a pintar por abajo y vas subiendo. ¿Qué pintarás lo último?» → el extremo de arriba).$t$,
  instrucciones_terapeuta = regexp_replace(regexp_replace(instrucciones_terapeuta, E'\n(Generalización \\(sondas\\):)', $t$
Fase 4 - Test de Transformación de Funciones a través de la red, sin entrenamiento directo (Luciano et al., 2009):

1. Diga las dos premisas y una tarea que exige ordenar los tres: "La muñeca está encima del plato. El plato está encima de la pelota. Empiezas a pintar por abajo y vas subiendo. ¿Qué pintarás lo último?" (respuesta: la muñeca). Desde el otro lado, la respuesta es el otro extremo.
2. No refuerce diferencialmente durante estos ensayos, pero registre la respuesta. Elegir el intermedio indica que no integra la red.
3. Prueba de conducta fuera de la tableta (sin registro): con cajas o vasos reales, "La pegatina está debajo de la caja azul. La caja azul está detrás de la silla. ¡Búscala!" (la pegatina, solo como premio al final).

\1$t$), E'(- Test de vínculo combinatorio:[^\n]*\n)', $t$\1- Transformación de funciones: C → A (pintando desde el lado de C: "¿Qué pintarás lo último?"; la respuesta es A) y A → C (desde el lado de A; la respuesta es C)
$t$)
where clinica_id is null and nombre = 'Derivar Relaciones Espaciales en Redes Combinatorias' and instrucciones_terapeuta not like '%Fase 4 - Test de Transformación de Funciones a través de la red%';
update programas_alumno pa set objetivo = pb.objetivo, secuencia_rft = pb.secuencia_rft, instrucciones_terapeuta = pb.instrucciones_terapeuta
from programas_base pb where pa.programa_base_id = pb.id and pb.clinica_id is null and pb.nombre = 'Derivar Relaciones Espaciales en Redes Combinatorias';

update programas_base set activo = false, orden = null where clinica_id is null and nombre = 'Transferir Funciones a través de Relaciones Espaciales';

